const expectedEventSecret = $env.CITYWALK_MARKETING_APPROVED_WEBHOOK_SECRET;
const providedEventSecret = $json.headers?.['x-citywalk-event-key'];

if (!expectedEventSecret || providedEventSecret !== expectedEventSecret) {
  throw new Error('Unauthorized approval event');
}

const envelope = $json.body ?? $json;

if (envelope.event !== 'marketing.content.approved') {
  throw new Error('Unsupported event');
}

const content = envelope.content;
if (!content || !Number.isInteger(content.id) || content.id <= 0) {
  throw new Error('Invalid content id');
}

if (String(content.platform ?? '').trim().toLowerCase() !== 'instagram') {
  throw new Error('Unsupported platform');
}

if (!Array.isArray(envelope.media) || envelope.media.length === 0) {
  throw new Error('Approved media is required');
}

let previousPosition = -1;
for (const [index, media] of envelope.media.entries()) {
  if (!media || !media.assetKey || !['image', 'video'].includes(media.kind)) {
    throw new Error(`Invalid media at index ${index}`);
  }
  if (!Number.isInteger(media.position) || media.position <= previousPosition) {
    throw new Error('Media must be in stable ascending order');
  }
  previousPosition = media.position;
}

return [{ json: envelope }];

const envelope = $('Validate Approval Event').first().json;
const contentId = envelope.content.id;

// Local state-machine test only. No external platform call happens here.
const publishedUrl = `https://mock.citywalk.invalid/instagram/${contentId}`;

return [{
  json: {
    contentId,
    publishedUrl,
    mock: true,
  },
}];
